<?php
declare(strict_types=1);require_once dirname(__DIR__).'/bootstrap.php';msp2RequireAccess();$q=msp2NormalizeText((string)($_GET['q']??''));$rows=[];$error=null;$params=[];$where='1=1';if($q!==''){$where='(nombre_locatario LIKE :q OR cdo_local LIKE :q OR CAST(id_contrato_arriendo AS NVARCHAR(20)) LIKE :q)';$params[':q']='%'.$q.'%';}try{$s=$conn->prepare("SELECT * FROM dbo.msp_vw_garantias_submayor_contable WHERE $where AND (monto_recibido>0 OR saldo_pasivo_contable<>0) ORDER BY nombre_locatario,cdo_local");$s->execute($params);$rows=$s->fetchAll()?:[];}catch(Throwable $e){$error='No fue posible cargar el submayor.';}function sgMonto(mixed $v):string{return '$ '.number_format((float)$v,0,',','.');}
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Submayor de garantías | MSP</title><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css"><link rel="stylesheet" href="/portalgp/styles.css"></head><body class="gp-layout bg-light"><?php include dirname(__DIR__,2).'/templates/header.php';?><main class="gp-main container-fluid py-4 px-lg-4"><div class="d-flex justify-content-between mb-3"><div><p class="text-muted mb-1">MSP / Contabilidad</p><h1 class="h3">Submayor de garantías</h1><p class="text-muted">Cruza el saldo operativo individual con el pasivo contable.</p></div><a class="btn btn-outline-dark btn-sm align-self-start" href="<?php echo msp2Escape(msp2Url('garantias/index.php'));?>">Volver a Garantías</a></div><form class="row g-2 mb-3"><div class="col-lg-10"><input name="q" class="form-control" value="<?php echo msp2Escape($q);?>" placeholder="Buscar arrendatario, contrato o local"></div><div class="col-lg-2 d-grid"><button class="btn btn-primary">Buscar</button></div></form><?php if($error):?><div class="alert alert-danger"><?php echo $error;?></div><?php endif;?><div class="card shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Arrendatario/local</th><th>Contrato</th><th class="text-end">Recibido</th><th class="text-end">Aplicado</th><th class="text-end">Devuelto</th><th class="text-end">Saldo operativo</th><th class="text-end">Pasivo contable</th><th class="text-end">Diferencia</th><th>Cuadre</th></tr></thead><tbody><?php if($rows===[]):?><tr><td colspan="9" class="text-center text-muted py-4">Sin movimientos.</td></tr><?php endif;foreach($rows as $r):?><tr><td><?php echo msp2Escape((string)$r['nombre_locatario']);?><div class="small text-muted">Local <?php echo msp2Escape((string)$r['cdo_local']);?> · Garantía #<?php echo (int)$r['id_garantia'];?></div></td><td>#<?php echo (int)$r['id_contrato_arriendo'];?></td><?php foreach(['monto_recibido','monto_aplicado','monto_devuelto','monto_disponible','saldo_pasivo_contable','diferencia'] as $k):?><td class="text-end"><?php echo sgMonto($r[$k]);?></td><?php endforeach;?><td><span class="badge text-bg-<?php echo $r['estado_cuadre']==='CUADRADO'?'success':'danger';?>"><?php echo msp2Escape((string)$r['estado_cuadre']);?></span></td></tr><?php endforeach;?></tbody></table></div></div></main></body></html>
